package design.knowledge.stamp.adoc.dialect;

/**
 * An inline reference or composition directive found on one line: it points beyond the line
 * and is regenerated by every parse, so it carries no identity of its own beyond the line and
 * its position among that line's references.
 *
 * @param kind   what the reference is
 * @param line   the 1-based line it occurs on
 * @param index  its position among the references on that line, from 0
 * @param target the anchor, key, path, attribute name or URL it points at, as written; an index
 *               term's text; a footnote's or estimate mark's note
 * @param text   the display text of a cross reference or link, an include's parameters, or
 *               {@code "negated"} for an {@code ifndef}; empty otherwise
 * @param raw    the macro as written, for exact read-back
 */
public record Reference(Kind kind, int line, int index, String target, String text, String raw) {

    /** The reference kinds, each a concept of the AsciiDoc document model. */
    public enum Kind {
        INDEX_TERM, CROSS_REFERENCE, CITATION, FOOTNOTE, LINK, ESTIMATE_MARK, INCLUDE, CONDITIONAL
    }

    /** @return whether an {@code ifndef} rather than an {@code ifdef} */
    public boolean negated() {
        return kind == Kind.CONDITIONAL && "negated".equals(text);
    }

    @Override
    public String toString() {
        return kind.name().toLowerCase() + "@" + line + ":" + index + " " + target + (text.isEmpty() ? "" : " [" + text + "]");
    }
}
